set -euo pipefail
# device.ts: split openOffline
perl -0pi -e 's|/\*\*\n \* Loses the connection with the channel.s row in view, then opens the\n \* channel from it.\n \*/\nexport async function openOffline\(\n  page: Page,\n  channel: Named\n\): Promise<Conversation> \{\n  await findRow\(page, channel\);\n  await goOffline\(page.context\(\)\);\n  return openFromList\(page, channel\);\n\}|/**\n * Loses the connection with the channel\x27s row in view, so that the channel\n * can then be opened from it. A check marked as failing sometimes takes this\n * step outside the mark, so that only the opening is excused.\n */\nexport async function loseConnectionAt(\n  page: Page,\n  channel: Named\n): Promise<void> {\n  await findRow(page, channel);\n  await goOffline(page.context());\n}\n\n/**\n * Loses the connection with the channel\x27s row in view, then opens the\n * channel from it.\n */\nexport async function openOffline(\n  page: Page,\n  channel: Named\n): Promise<Conversation> {\n  await loseConnectionAt(page, channel);\n  return openFromList(page, channel);\n}|' harness/device.ts
grep -q loseConnectionAt harness/device.ts
# wrapped opens: move the offline step out of the mark
perl -0pi -e 's|(  // Defect[^\n]*\n(?:  //[^\n]*\n)*)  await failsSometimes\(async \(\) => \{\n    const offline = await openOffline\(page, (\w+)\);|  await loseConnectionAt(page, $2);\n$1  await failsSometimes(async () => {\n    const offline = await openFromList(page, $2);|g' offline.spec.ts
perl -0pi -e 's|(  // Defect[^\n]*\n(?:  //[^\n]*\n)*)  await failsSometimes\(async \(\) => \{\n    const offline = await openOffline\(first, made.channel\);|  await loseConnectionAt(first, made.channel);\n$1  await failsSometimes(async () => {\n    const offline = await openFromList(first, made.channel);|' current.spec.ts
perl -0pi -e 's|  findRow,\n  openFromList,\n  openOffline,|  findRow,\n  loseConnectionAt,\n  openFromList,\n  openOffline,|' offline.spec.ts
perl -0pi -e 's|  type Named,\n  openFromList,\n  openOffline,|  loseConnectionAt,\n  type Named,\n  openFromList,|' current.spec.ts
# SYN-06 / SYN-08: read the way that leaves the channel on the device
perl -0pi -e 's|  const first = await pageFor\(.ben.\);\n  const view = new Conversation\(first, made.channel.id\);\n  await view.open\(\);\n  await expectShown\(view, AT_FIRST\);\n  const blank|  const first = await pageFor(\x27ben\x27);\n  const view = await readAndReturn(first, made.channel, made.elsewhere);\n  await expectShown(view, AT_FIRST);\n  const blank|g' current.spec.ts
